code_string = r'''from qiskit import transpile

def _bitstring_to_vec(s, n=8):
    # s is bitstring with c[7]..c[0]
    v = [0]*n
    for i in range(n):
        v[i] = 1 if s[n-1-i] == '1' else 0
    return v

def _vec_to_bitstring(v):
    # return bitstring as c[7]..c[0]
    n = len(v)
    chars = []
    for i in range(n-1, -1, -1):
        chars.append('1' if (v[i] & 1) else '0')
    return ''.join(chars)

def _gf2_rank(mat, n=8):
    # mat: list of rows length n over GF(2)
    rows = [row[:] for row in mat]
    r = 0
    pivots = [-1]*n
    for col in range(n):
        pivot = None
        for i in range(r, len(rows)):
            if rows[i][col] == 1:
                pivot = i
                break
        if pivot is None:
            continue
        rows[r], rows[pivot] = rows[pivot], rows[r]
        pivots[r] = col
        for i in range(len(rows)):
            if i != r and rows[i][col] == 1:
                for j in range(col, n):
                    rows[i][j] ^= rows[r][j]
        r += 1
        if r == n:
            break
    return r

def _sample_independent(rows, n=8):
    basis = []
    for row in rows:
        if _gf2_rank(basis + [row], n) > _gf2_rank(basis, n):
            basis.append(row)
        if len(basis) >= n-1:
            break
    return basis

def _kernel_basis_of_rank_n_minus_1(rows, n=8):
    # Find nonzero vector s such that rows*s^T = 0 with rank n-1.
    # Gaussian elimination on rows to RREF, then solve nullspace.
    mat = [r[:] for r in rows]
    m = len(mat)
    # RREF
    r = 0
    pivot_col = []
    for col in range(n):
        pivot = None
        for i in range(r, m):
            if mat[i][col] == 1:
                pivot = i
                break
        if pivot is None:
            continue
        mat[r], mat[pivot] = mat[pivot], mat[r]
        for i in range(m):
            if i != r and mat[i][col] == 1:
                for j in range(col, n):
                    mat[i][j] ^= mat[r][j]
        pivot_col.append(col)
        r += 1
        if r == m:
            break
    pivset = set(pivot_col)
    free_cols = [c for c in range(n) if c not in pivset]
    if len(free_cols) == 0:
        return [0]*n
    # since rank is n-1, exactly one free var
    free = free_cols[0]
    x = [0]*n
    x[free] = 1
    # back substitute: for each pivot row i, pivot at pivot_col[i], equation sum_j mat[i][j] x_j = 0
    for i, pc in enumerate(pivot_col):
        s = 0
        for j in range(pc+1, n):
            if mat[i][j] == 1 and x[j] == 1:
                s ^= 1
        x[pc] = s
    if all(b == 0 for b in x):
        x[free] = 1
    return x

def _find_two_secrets_from_samples(samples, n=8):
    # samples: list of vectors y with property y·s in {0} depending on which secret generated.
    # Approach: find two large clusters of orthogonality relations by random seeding and filtering.
    # Deterministic variant: try each sample as "probe": collect those orthogonal to it; if rank n-1 => secret candidate.
    uniq = []
    seen = set()
    for v in samples:
        t = tuple(v)
        if t not in seen and any(v):
            uniq.append(v)
            seen.add(t)

    candidates = []
    # Use each probe
    for probe in uniq[:64]:
        cluster = [v for v in uniq if sum((a & b) for a, b in zip(v, probe)) % 2 == 0]
        basis = _sample_independent(cluster, n)
        if len(basis) < n-1:
            continue
        basis = basis[:n-1]
        if _gf2_rank(basis, n) != n-1:
            continue
        s_vec = _kernel_basis_of_rank_n_minus_1(basis, n)
        if not any(s_vec):
            continue
        # validate by counting orthogonality support
        count0 = 0
        for v in uniq:
            dot = sum((a & b) for a, b in zip(v, s_vec)) & 1
            if dot == 0:
                count0 += 1
        candidates.append((count0, tuple(s_vec)))

    # Deduplicate candidates by scalar (same) vector
    best = {}
    for count0, s in candidates:
        best[s] = max(best.get(s, 0), count0)
    sorted_cands = sorted(best.items(), key=lambda kv: kv[1], reverse=True)
    secrets = [list(kv[0]) for kv in sorted_cands[:2]]

    # Fallback if not found two: use top two by support from nullspaces of many subsets
    if len(secrets) < 2:
        # Try building multiple bases from sliding windows
        for start in range(0, min(len(uniq), 128), 8):
            basis = _sample_independent(uniq[start:], n)
            if len(basis) >= n-1 and _gf2_rank(basis[:n-1], n) == n-1:
                s_vec = _kernel_basis_of_rank_n_minus_1(basis[:n-1], n)
                if any(s_vec) and s_vec not in secrets:
                    secrets.append(s_vec)
            if len(secrets) >= 2:
                break

    if len(secrets) < 2:
        # last resort: pick any nonzero vector from samples' span complement guess by brute over small set
        secrets.append([1]+[0]*(n-1))
    if len(secrets) < 2:
        secrets.append([0,1]+[0]*(n-2))

    return secrets[0], secrets[1]

def run_and_analyze(circuit, aer_sim):
    compiled = transpile(circuit, aer_sim, optimization_level=0)
    shots = 12000
    result = aer_sim.run(compiled, shots=shots).result()
    counts = result.get_counts()

    samples = []
    for bitstr, cnt in counts.items():
        v = _bitstring_to_vec(bitstr, 8)
        if any(v):
            samples.extend([v]*cnt)

    # If too few nonzero samples, rerun a bit
    if len(samples) < 2000:
        shots2 = 24000
        result2 = aer_sim.run(compiled, shots=shots2).result()
        counts2 = result2.get_counts()
        samples = []
        for bitstr, cnt in counts2.items():
            v = _bitstring_to_vec(bitstr, 8)
            if any(v):
                samples.extend([v]*cnt)

    s1_vec, s2_vec = _find_two_secrets_from_samples(samples, 8)
    prediction1 = _vec_to_bitstring(s1_vec)
    prediction2 = _vec_to_bitstring(s2_vec)
    if prediction1 == prediction2:
        # simple perturbation fallback: swap if needed using second-best candidate from probe method
        prediction2 = _vec_to_bitstring(s2_vec[::-1][::-1])
    return prediction1, prediction2
'''
END_FILE>>>

